SELECT a.id, a.reference_signal_id, a.evaluation_path, a.evaluated_at, UNIX_TIMESTAMP(a.evaluated_at) AS eval_epoch, a.five_minute_signal_id, a.five_minute_raw_decision, a.five_minute_effective_decision, a.five_minute_age_seconds, a.five_minute_data_quality_valid, a.one_hour_signal_id, a.one_hour_raw_decision, a.one_hour_effective_decision, a.one_hour_data_quality_valid, a.assessment_band, a.max_initial_percent, a.legacy_veto_result, a.final_result, LEFT(a.final_reason, 300) AS final_reason FROM buy_htf_assessment_audit a WHERE a.reference_signal_id IN (156723,159408,165412,165415,167668,171589,176710) ORDER BY a.reference_signal_id, a.evaluated_at LIMIT 50